"""Read native input and total-force decimal tokens independently of ASE."""
import re
import shlex
import numpy as np

NUMBER=r'[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[EeDd][-+]?\d+)?'
FORCE=re.compile(r'^\s*atom\s+(\d+)\s+type\s+(\d+)\s+force\s*=\s*('+NUMBER+r')\s+('+NUMBER+r')\s+('+NUMBER+r')\s*$',re.M)


def singleton(pattern,text):
    matches=re.findall(pattern,text,re.M)
    if len(matches)!=1:
        raise ValueError(f'Expected singleton {pattern}, found {len(matches)}')
    return matches[0]


def number(token):
    return float(token.replace('D','E').replace('d','e'))


def input_text(text):
    lines=text.splitlines()
    pairs=re.findall(r'^\s*([\w_]+(?:\(\d+\))?)\s*=\s*([^,\n]+)',text,re.M)
    if len(dict(pairs))!=len(pairs):
        raise ValueError('Duplicate native setting')
    values={k:v.strip().strip("'") for k,v in pairs}
    nat,ntyp=int(values['nat']),int(values['ntyp'])
    def card(header,count):
        if lines.count(header)!=1:
            raise ValueError('Missing/duplicate native card '+header)
        start=lines.index(header)+1
        return [shlex.split(line) for line in lines[start:start+count]]
    positions=card('ATOMIC_POSITIONS angstrom',nat)
    species=card('ATOMIC_SPECIES',ntyp)
    if any(len(row)!=4 for row in positions) or any(len(row)!=3 for row in species):
        raise ValueError('Incomplete or constrained native geometry')
    return {'values':values,'symbols':[r[0] for r in positions],
            'position_tokens':[r[1:] for r in positions],
            'positions':np.array([[number(x) for x in r[1:]] for r in positions]),
            'cell':np.array(card('CELL_PARAMETERS angstrom',3),float),
            'species':species,'kpoints':list(map(int,card('K_POINTS automatic',1)[0]))}


def stdout_text(text,nat,symbols):
    sections=text.split('Forces acting on atoms (cartesian axes, Ry/au):')
    if len(sections)!=2 or 'The non-local contrib.' not in sections[1]:
        raise ValueError('Missing/duplicate total-force boundary')
    total=sections[1].split('The non-local contrib.',1)[0]
    rows=FORCE.findall(total)
    if len(rows)!=nat or len(re.findall(r'\batom\b',total))!=nat:
        raise ValueError('Incomplete/malformed total-force table')
    ids=[int(r[0]) for r in rows]; types=[int(r[1]) for r in rows]
    expected=[1 if symbol=='Ni' else 2 for symbol in symbols]
    if ids!=list(range(1,nat+1)) or types!=expected:
        raise ValueError('Force atom order/type mismatch')
    geom=text.split('positions (alat units)')
    if len(geom)!=2:
        raise ValueError('Ambiguous stdout geometry')
    atoms=re.findall(r'(\d+)\s+(Ni|H)\s+tau\(\s*(\d+)\)\s*=\s*\(\s*('+NUMBER+r')\s+('+NUMBER+r')\s+('+NUMBER+r')',geom[1].split('Crystallographic axes')[0])
    if [(int(r[0]),r[1],int(r[2])) for r in atoms]!=[(i,s,i) for i,s in enumerate(symbols,1)]:
        raise ValueError('Stdout atom identity/order mismatch')
    axes=re.findall(r'a\(\d\) = \(\s*('+NUMBER+r')\s+('+NUMBER+r')\s+('+NUMBER+r')',text)
    if len(axes)!=3 or text.count('JOB DONE.')!=1 or 'convergence NOT achieved' in text:
        raise ValueError('Missing complete converged native stdout')
    return {'force_tokens':[list(r[2:]) for r in rows], 'force_ids':ids,'force_types':types,
            'energy_ry':singleton(r'^!\s+total energy\s*=\s*('+NUMBER+r')\s+Ry',text),
            'total_moment':re.findall(r'total magnetization\s*=\s*('+NUMBER+r')',text)[-1],
            'absolute_moment':re.findall(r'absolute magnetization\s*=\s*('+NUMBER+r')',text)[-1],
            'iterations':int(singleton(r'convergence has been achieved in\s+(\d+) iterations',text)),
            'scf_accuracy_ry':re.findall(r'estimated scf accuracy\s*<\s*('+NUMBER+r')\s+Ry',text)[-1],
            'alat_bohr':singleton(r'celldm\(1\)=\s*('+NUMBER+r')',text),
            'axes':np.array(axes,float),
            'fractional':np.array([[number(x) for x in r[3:]] for r in atoms]),
            'version':singleton(r'Program PWSCF v\.([^\s]+)',text),'job_done':True}

"""Resolve registered raw sources and closed package/snapshot graphs by bytes."""
import hashlib
import json
from pathlib import Path

PLAN=Path('/home/administrator/projects/substrate-ni-collective/proposals/P254-ni-collective-response/W1-loaded-force-sensitivity-plan.json')
PLAN_SHA='81d7f2b69ada5cda84900b64a1e833b0be6a87c2e97d1970f7521b90843f67be'
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[3]


def digest(path):
    with Path(path).open('rb') as stream:
        return hashlib.file_digest(stream,'sha256').hexdigest()


def load(path):
    return json.loads(Path(path).read_bytes())


def fingerprint(value):
    return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(',',':'),allow_nan=False).encode()).hexdigest()


def source_binding_valid(binding):
    path,expected=binding
    return digest(path)==expected


def records(value):
    if isinstance(value,dict):
        if isinstance(value.get('path'),str) and 'sha256' in value:
            yield value['path'],value['sha256']
        for key,item in value.items():
            if key.startswith('/') and isinstance(item,dict) and 'sha256' in item:
                yield key,item['sha256']
            yield from records(item)
    elif isinstance(value,list):
        for item in value:
            yield from records(item)


def closed_graph():
    if digest(PLAN)!=PLAN_SHA:
        raise ValueError('Registration bytes changed')
    plan=load(PLAN); access=Path(plan['source_access']['path'])
    if digest(access)!=plan['source_access']['sha256']:
        raise ValueError('Source access inventory changed')
    inventory=load(access); report=load(plan['native_wave']['report']['path'])
    references={(str(PLAN),PLAN_SHA),(str(access),digest(access))}
    references.update(records(inventory)); references.update(records(report))
    snapshots={}; packages=[]
    for package in report['generation_packages']:
        package_data=load(package['package']['path']); packages.append(package_data)
        references.update(records(package_data))
        snapshot=load(package['source_snapshot']['path'])
        for original,item in snapshot.items():
            saved=Path(item['snapshot'])
            references.add((str(saved),item['sha256']))
            snapshots[(original,item['sha256'])]=str(saved)
    # Every declared source in every completed native spec, not just 71 roots.
    specs=[]
    for row in inventory['raw_registered_sources']:
        if row['path'].endswith('/scf/result.json'):
            result=load(row['path']); spec=load(result['data']['artifacts']['spec.json']['path'])
            specs.append(spec)
            for original,sha in spec['input_files_sha256'].items():
                references.add((original,sha))
    verified=[]
    for path,sha in sorted(references):
        actual=snapshots.get((path,sha),path)
        if not source_binding_valid((actual,sha)):
            raise ValueError('Raw source graph byte mismatch: '+path+' via '+actual)
        verified.append({'path':path,'sha256':sha,'consumed_path':actual,'bytes':Path(actual).stat().st_size})
    for row in inventory['current_method_sources'][:2]:
        copied=ROOT/'src/substrate_framework'/Path(row['path']).name
        if not source_binding_valid((copied,row['sha256'])):
            raise ValueError('Imported method differs from captured current source: '+str(copied))
    return {'plan':plan,'inventory':inventory,'native_report':report,'verified':verified,
            'specs':specs,'packages':packages}


def own_sources():
    paths=list(HERE.glob('*.py'))+[ROOT/'src/substrate_framework/material_force_sensitivity.py',
        ROOT/'src/substrate_framework/material_primary_boundary.py',ROOT/'src/substrate_framework/verification.py']
    return {str(path):digest(path) for path in sorted(paths)}


def run(ledger,context):
    graph=closed_graph(); manifest=context['manifest']
    ledger.check('registered full raw source/model/package graph matches prepared exact bytes',
                 graph['verified']==manifest['upstream_verified'] and own_sources()==manifest['oracle_sources'])
    method=graph['inventory']['current_method_sources'][0]
    imported=ROOT/'src/substrate_framework'/Path(method['path']).name
    other=ROOT/'src/substrate_framework/verification.py'
    ledger.mutation_sensitive('load-bearing current-method source substitution and digest corruption',
        source_binding_valid,(imported,method['sha256']),
        [(other,method['sha256']),(imported,'0'*64)])
    context.update(graph)
    return {'verified_sources':graph['verified'],'registered_raw_count':len(graph['inventory']['raw_registered_sources']),
            'registered_current_method_count':len(graph['inventory']['current_method_sources']),
            'nanosecond_metadata_used_as_proof':False,'snapshot_resolution':'Each declared hash resolved to frozen raw object when available; direct bytes otherwise.'}

"""Exact printed-decimal boxes and unprojected per-atom force differences.

These enclose printing alone, not SCF or discretization error. Units and gates
are explicit caller inputs; no material or engine convention is implicit.
"""
from decimal import Decimal, InvalidOperation
import re

import sympy as sp

_DECIMAL = re.compile(r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eEdD][-+]?\d+)?\Z")


def printed_interval(token):
    """Return exact center and half last-place quantum, including exponent."""
    if not isinstance(token, str) or not _DECIMAL.fullmatch(token):
        raise ValueError('Expected a finite native decimal lexeme')
    try:
        decimal = Decimal(token.replace('D', 'E').replace('d', 'e'))
    except InvalidOperation as error:
        raise ValueError('Invalid decimal') from error
    return sp.Rational(str(decimal)), sp.Rational(10) ** decimal.as_tuple().exponent / 2


def difference_box(first, second, factor):
    """Minkowski difference of two printed 3-vectors in positive output units."""
    factor = sp.sympify(factor)
    if factor.is_positive is not True or len(first) != 3 or len(second) != 3:
        raise ValueError('Positive conversion and exactly three components required')
    result = []
    for left, right in zip(first, second):
        a, ra = printed_interval(left)
        b, rb = printed_interval(right)
        result.append(((a-b-ra-rb)*factor, (a-b+ra+rb)*factor))
    return tuple(result)


def box_norm_squared(box):
    """Exact extrema of sum x_i**2 on a closed Cartesian component box."""
    if len(box) != 3 or any(lo > hi for lo, hi in box):
        raise ValueError('Expected three ordered intervals')
    lower = sum(0 if lo <= 0 <= hi else min(lo*lo, hi*hi) for lo, hi in box)
    upper = sum(max(lo*lo, hi*hi) for lo, hi in box)
    return sp.simplify(lower), sp.simplify(upper)


def vector_difference_squared(first, second, factor):
    """Full raw Euclidean squared difference of exact printed centers."""
    if len(first) != 3 or len(second) != 3 or sp.sympify(factor).is_positive is not True:
        raise ValueError('Positive conversion and exactly three components required')
    return sum((printed_interval(a)[0]-printed_interval(b)[0])**2
               for a, b in zip(first, second)) * factor**2


def max_force_difference(first, second, factor):
    """Per-atom squares and exact extrema of their maximum, with no projection."""
    if not first or len(first) != len(second):
        raise ValueError('Nonempty equally ordered atom arrays required')
    factor = sp.sympify(factor)
    if factor.is_positive is not True:
        raise ValueError('Positive unit conversion required')
    centers, lowers, uppers = [], [], []
    for a, b in zip(first, second):
        centers.append(vector_difference_squared(a, b, sp.S.One))
        lo, hi = box_norm_squared(difference_box(a, b, sp.S.One))
        lowers.append(lo)
        uppers.append(hi)
    scale = factor**2
    return {'center_squared': max(centers)*scale, 'lower_squared': max(lowers)*scale,
            'upper_squared': max(uppers)*scale,
            'per_atom_center_squared': [x*scale for x in centers],
            'per_atom_lower_squared': [x*scale for x in lowers],
            'per_atom_upper_squared': [x*scale for x in uppers],
            'max_center_atom_1based': centers.index(max(centers))+1}


def printing_decision(lower_squared, upper_squared, gate):
    """Strict below/above or inconclusive against an exact nonnegative gate."""
    gate = sp.sympify(gate)
    if gate.is_nonnegative is not True or not 0 <= lower_squared <= upper_squared:
        raise ValueError('Nonnegative ordered bounds and gate required')
    if upper_squared < gate**2:
        return 'guaranteed_below'
    if lower_squared > gate**2:
        return 'guaranteed_above'
    return 'print_inconclusive'


def scalar_difference_interval(first, second, factor=sp.S.One):
    """Exact signed first-minus-second printing interval in explicit units."""
    if sp.sympify(factor).is_positive is not True:
        raise ValueError('Positive unit conversion required')
    a, ra = printed_interval(first)
    b, rb = printed_interval(second)
    return ((a-b-ra-rb)*factor, (a-b+ra+rb)*factor)
